package org.sleepwell.app;
import org.json.*;import javax.net.ssl.*;import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.*;import java.security.*;import java.security.cert.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import java.util.function.BooleanSupplier;
/** Per-client pinned TLS, standard bridge-name verification, bounded close-only HTTP/1.1. */
final class HueBridgeClient implements AutoCloseable {
 static final int LIMIT=256*1024;private final HueBridgeConfig config;private final BooleanSupplier admitted;private final AtomicReference<Socket> socket=new AtomicReference<>();private volatile boolean closed;private volatile long deadline;
 HueBridgeClient(HueBridgeConfig config,BooleanSupplier admitted){this.config=config;this.admitted=admitted;}
 private void current()throws IOException{if(closed||!admitted.getAsBoolean()||deadline!=0&&System.nanoTime()-deadline>=0)throw new InterruptedIOException("Bridge operation cancelled or its owner changed.");}
 private static byte[] fingerprint(X509Certificate certificate)throws CertificateException{try{return MessageDigest.getInstance("SHA-256").digest(certificate.getEncoded());}catch(NoSuchAlgorithmException impossible){throw new CertificateException(impossible);}}
 private X509TrustManager trust(){byte[] wanted=new byte[32];for(int n=0;n<wanted.length;n++)wanted[n]=(byte)Integer.parseInt(config.pin.substring(n*2,n*2+2),16);return new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] chain,String auth)throws CertificateException{throw new CertificateException("Client certificates are unsupported");}public void checkServerTrusted(X509Certificate[] chain,String auth)throws CertificateException{if(chain==null||chain.length<1||chain.length>8)throw new CertificateException("Missing bridge certificate");chain[0].checkValidity();if(!MessageDigest.isEqual(wanted,fingerprint(chain[0])))throw new CertificateException("Bridge certificate differs from the explicit pin");}};}
 String request(String method,String path,JSONObject body)throws Exception{config.source();if(!Set.of("GET","POST","PUT").contains(method)||!path.matches("/api(?:/[A-Za-z0-9_-]{10,128}/lights(?:/[1-9][0-9]{0,5}(?:/state)?)?)?"))throw new IllegalArgumentException("Unsupported Hue endpoint");deadline=System.nanoTime()+15_000_000_000L;current();Socket raw=new Socket();if(!socket.compareAndSet(null,raw))throw new IllegalStateException("A bridge request is already running.");try{raw.connect(new InetSocketAddress(InetAddress.getByAddress(config.addressBytes()),443),4000);raw.setSoTimeout(4000);current();SSLContext tls=SSLContext.getInstance("TLS");tls.init(null,new TrustManager[]{trust()},new SecureRandom());SSLSocket secure=(SSLSocket)tls.getSocketFactory().createSocket(raw,config.identity,443,true);if(!socket.compareAndSet(raw,secure)){secure.close();throw new InterruptedIOException("Bridge operation cancelled.");}List<String> protocols=new ArrayList<>();for(String supported:secure.getSupportedProtocols())if(supported.equals("TLSv1.3")||supported.equals("TLSv1.2"))protocols.add(supported);if(protocols.isEmpty())throw new SSLException("TLS1.2 or newer is unavailable");secure.setEnabledProtocols(protocols.toArray(new String[0]));SSLParameters parameters=secure.getSSLParameters();parameters.setEndpointIdentificationAlgorithm("HTTPS");secure.setSSLParameters(parameters);secure.setSoTimeout(4000);secure.startHandshake();current();if(!HttpsURLConnection.getDefaultHostnameVerifier().verify(config.identity,secure.getSession()))throw new SSLPeerUnverifiedException("Bridge TLS identity does not match the entered identity");X509Certificate peer=(X509Certificate)secure.getSession().getPeerCertificates()[0];peer.checkValidity();byte[] actual=fingerprint(peer),wanted=new byte[32];for(int n=0;n<32;n++)wanted[n]=(byte)Integer.parseInt(config.pin.substring(n*2,n*2+2),16);if(!MessageDigest.isEqual(actual,wanted))throw new SSLPeerUnverifiedException("Bridge certificate pin changed");
  byte[] payload=body==null?new byte[0]:body.toString().getBytes(StandardCharsets.UTF_8);if(payload.length>4096)throw new IOException("Bridge request exceeds its limit.");String header=method+" "+path+" HTTP/1.1\r\nHost: "+config.identity+"\r\nAccept: application/json\r\nAccept-Encoding: identity\r\nConnection: close\r\n"+(body==null?"":"Content-Type: application/json\r\nContent-Length: "+payload.length+"\r\n")+"\r\n";current();OutputStream output=secure.getOutputStream();output.write(header.getBytes(StandardCharsets.US_ASCII));output.write(payload);output.flush();InputStream input=secure.getInputStream();String status=line(input,4096);if(!status.matches("HTTP/1\\.[01] [0-9]{3}(?: .*)?"))throw new IOException("Unsupported bridge HTTP response.");int code=Integer.parseInt(status.substring(9,12));if(code<200||code>=300)throw new IOException("Bridge rejected the request (HTTP "+code+"). No redirect or HTTP fallback is used.");Map<String,String> headers=new HashMap<>();int total=0;for(int n=0;;n++){String row=line(input,4096);total+=row.length();if(row.isEmpty())break;if(n>=64||total>16384)throw new IOException("Bridge response headers exceed their limit.");int colon=row.indexOf(':');if(colon<1)throw new IOException("Invalid bridge HTTP headers.");String name=row.substring(0,colon).toLowerCase(Locale.ROOT),value=row.substring(colon+1).strip();if(!name.matches("[a-z0-9-]+")||headers.put(name,value)!=null)throw new IOException("Ambiguous bridge HTTP headers.");}String encoding=headers.getOrDefault("content-encoding","identity");if(!encoding.equalsIgnoreCase("identity"))throw new IOException("Compressed bridge responses are unsupported.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();String transfer=headers.get("transfer-encoding"),length=headers.get("content-length");if(transfer!=null){if(!transfer.equalsIgnoreCase("chunked")||length!=null)throw new IOException("Ambiguous bridge response framing.");for(;;){String size=line(input,128);int extension=size.indexOf(';');if(extension>=0)size=size.substring(0,extension);if(!size.matches("[a-fA-F0-9]{1,8}"))throw new IOException("Invalid bridge chunk.");long count=Long.parseLong(size,16);if(count>LIMIT-bytes.size())throw new IOException("Bridge metadata exceeds256KiB.");if(count==0){for(int n=0;;n++){String trailer=line(input,4096);if(trailer.isEmpty())break;if(n>=16)throw new IOException("Too many bridge trailers.");}break;}copy(input,bytes,(int)count);if(!line(input,2).isEmpty())throw new IOException("Invalid chunk ending.");}}
  else if(length!=null){if(!length.matches("0|[1-9][0-9]{0,6}"))throw new IOException("Invalid bridge response length.");int count=Integer.parseInt(length);if(count>LIMIT)throw new IOException("Bridge metadata exceeds256KiB.");copy(input,bytes,count);}else{byte[] block=new byte[4096];for(int count;(count=input.read(block))!=-1;){current();if(count==0)throw new IOException("Bridge returned no data.");if(count>LIMIT-bytes.size())throw new IOException("Bridge metadata exceeds256KiB.");bytes.write(block,0,count);}}
  current();try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes.toByteArray())).toString();}catch(CharacterCodingException invalid){throw new IOException("Bridge returned invalid UTF-8 metadata.");}
 }finally{deadline=0;Socket owned=socket.getAndSet(null);if(owned!=null)try{owned.close();}catch(IOException ignored){}else try{raw.close();}catch(IOException ignored){}}}
 private void copy(InputStream input,OutputStream out,int count)throws IOException{byte[] block=new byte[4096];while(count>0){current();int read=input.read(block,0,Math.min(count,block.length));if(read<=0)throw new EOFException("Bridge response ended early.");out.write(block,0,read);count-=read;}}
 private String line(InputStream input,int max)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();while(bytes.size()<=max){current();int value=input.read();if(value<0)throw new EOFException("Bridge headers ended early.");if(value=='\r'){if(input.read()!='\n')throw new IOException("Bridge line ending is unsupported.");return new String(bytes.toByteArray(),StandardCharsets.US_ASCII);}if(value<' '||value>126)throw new IOException("Bridge HTTP header contains unsupported characters.");bytes.write(value);}throw new IOException("Bridge HTTP line exceeds its limit.");}
 @Override public void close(){closed=true;Socket own=socket.getAndSet(null);if(own!=null)try{own.close();}catch(IOException ignored){}}
}
